def compute_age_hours(created_at_i):
    now = int(time.time())
    return (now - created_at_i) / 3600

def compute_score(points, num_comments, created_at_i):
    hours = compute_age_hours(created_at_i)
    age_penalty = max(0, (hours - 12) * 2)
    score = points + 1.5 * num_comments - age_penalty
    return score

def categorize_story(title, url):
    title_lower = title.lower()
    keywords = {
        "AI & agents": ["ai", "agent", "llm", "model", "claude", "anthropic", "deepseek", "mai", "machine learning"],
        "Security & privacy": ["security", "privacy", "encryption", "breach", "verification", "surveillance", "adafruit", "flux", "gmail"],
        "Infra & devtools": ["kubernetes", "docker", "systemd", "backend", "devops", "qbe", "compiler", "kde", "plasma", "x11"],
        "Languages & tools": ["janet", "clojure", "bqn", "gleam", "programming"],
        "Science & culture": ["fidonet", "historical", "dos", "repair", "moergo", "keyboard"],
    }

    for category, kws in keywords.items():
        if any(kw in title_lower for kw in kws):
            return category
    return "Misc"

candidates = []

# Add from Algolia front_page
for hit in algolia_data.get('hits', []):
    candidates.append({
        'id': hit['objectID'],
        'title': hit['title'],
        'url': hit['url'],
        'points': hit['points'],
        'num_comments': hit.get('num_comments', 0),
        'created_at_i': hit.get('created_at_i', int(time.time())),
    })

# Dedupe by id (keep Algolia version which has metadata)
seen_ids = set(c['id'] for c in candidates)

# Filter and score
candidates_scored = []
for c in candidates:
    score = compute_score(c['points'], c['num_comments'], c['created_at_i'])
    c['score'] = score
    c['category'] = categorize_story(c['title'], c['url'])
    if score >= 80:
        candidates_scored.append(c)

# Sort by score
candidates_scored.sort(key=lambda x: x['score'], reverse=True)

print(f"Candidates after filtering (score >= 80): {len(candidates_scored)}")
for c in candidates_scored[:10]:
    print(f"  {c['id']} | {c['category']:20} | {c['score']:6.0f} | {c['title'][:50]}")
